import os
import subprocess
import sys
import tempfile
import unittest

sys.path.insert(0, os.path.dirname(__file__))
import release_notes  # noqa: E402


def git(cwd, *args):
    subprocess.run(["git", *args], cwd=cwd, check=True, capture_output=True,
                   env={**os.environ, "GIT_AUTHOR_NAME": "t", "GIT_AUTHOR_EMAIL": "t@t",
                        "GIT_COMMITTER_NAME": "t", "GIT_COMMITTER_EMAIL": "t@t"})


class History(unittest.TestCase):
    def setUp(self):
        self.dir = tempfile.TemporaryDirectory()
        self.old = os.getcwd()
        os.chdir(self.dir.name)
        git(".", "init", "-q", "-b", "main")
        git(".", "commit", "-q", "--allow-empty", "-m", "Initial commit")
        git(".", "tag", "v0.1.0")
        git(".", "commit", "-q", "--allow-empty", "-m", "direct fix")
        git(".", "checkout", "-q", "-b", "feature")
        git(".", "commit", "-q", "--allow-empty", "-m", "work on the feature")
        git(".", "checkout", "-q", "main")
        git(".", "merge", "-q", "--no-ff", "feature", "-m", "Merge pull request #12 from o/feature", "-m", "Add the feature")
        git(".", "commit", "-q", "--allow-empty", "-m", "Squashed thing (#13)")

    def tearDown(self):
        os.chdir(self.old)
        self.dir.cleanup()

    def test_pr_numbers_and_direct_commits_with_no_blank_entries(self):
        got = release_notes.history("v0.1.0")
        self.assertEqual([(e[1], e[3]) for e in got], [
            ("Squashed thing (#13)", 13),
            ("Merge pull request #12 from o/feature", 12),
            ("direct fix", None),
        ])
        for sha, subject, _, _ in got:
            self.assertEqual(len(sha), 40)
            self.assertTrue(subject)

    def test_first_release_walks_everything(self):
        subjects = [e[1] for e in release_notes.history("")]
        self.assertEqual(subjects[-1], "Initial commit")
        self.assertNotIn("", subjects)

    def test_clean_body_drops_footers_and_demotes_headings(self):
        body = "## Why\n\nBecause.\n\n🤖 Generated with [Claude Code](https://x)\n\nhttps://claude.ai/code/session_1\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_"
        self.assertEqual(release_notes.clean_body(body), "**Why**\n\nBecause.")


if __name__ == "__main__":
    unittest.main()
